else if (GlobalScript.inst.gameState.number_event == 19)
{
	text2 = "Five \"no\"";
	text = "Congratulations on your appointment to the post of Premier of the State Council of the People's Republic of China, Comrade Hua Guofeng. As you know, your predecessor was Zhou Enlai, who gained popularity and respect among the people at home and abroad for his honesty and administrative talents. However, he was also an active promoter of economic reforms and promoted reformers in the party, such as his protege Deng Xiaoping. For these reasons, the death of Zhou on January 8, 1976 caused great grief among the people, which dissatisfied Mao and the leadership of the CCP, who reacted very reservedly to his death. Rumor has it Mao Zedong himself set the campaign of Five \"no\" in motion — not to wear mourning bands, not to make wreaths, not to make memorials, not to hold memorial ceremonies and not to hang photos of Zhou Enlai — yet no one is sure, since Mao is now barely reachable because of his bad legs and overall health, and decisions have to be made quickly with no time to wait. And you, as a new prime minister, can influence its execution.";
}
